from AlgorithmImports import *
from collections import deque
from decimal import Decimal, ROUND_FLOOR


class ParallelStrategySystemAlgorithm(QCAlgorithm):
    SPY_MOVING_AVERAGE_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.Settings.DailyPreciseEndTime = True

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_moving_average = SimpleMovingAverage(
            self.SPY_MOVING_AVERAGE_PERIOD
        )
        self.aapl_rsi = RelativeStrengthIndex(
            self.AAPL_RSI_PERIOD, MovingAverageType.Wilders
        )

        self.spy_ready_points = deque(maxlen=2)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.last_spy_update = None
        self.last_aapl_update = None
        self.last_evaluation_time = None

    def OnData(self, data):
        bars = {
            symbol: self._get_real_bar(data, symbol)
            for symbol in self.symbols.values()
        }

        spy_bar = bars[self.spy]
        if spy_bar is not None and spy_bar.EndTime != self.last_spy_update:
            self.spy_moving_average.Update(spy_bar.EndTime, spy_bar.Close)
            self.last_spy_update = spy_bar.EndTime

            if self.spy_moving_average.IsReady:
                self.spy_ready_points.append(
                    (spy_bar.Close, self.spy_moving_average.Current.Value)
                )

        aapl_bar = bars[self.aapl]
        if aapl_bar is not None and aapl_bar.EndTime != self.last_aapl_update:
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.last_aapl_update = aapl_bar.EndTime

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close

        if any(bar is None for bar in bars.values()):
            return

        evaluation_time = spy_bar.EndTime
        if evaluation_time == self.last_evaluation_time:
            return
        self.last_evaluation_time = evaluation_time

        if (
            len(self.spy_ready_points) < 2
            or not self.aapl_rsi.IsReady
            or self.aapl_previous_close is None
        ):
            return

        previous_spy_close, previous_spy_average = self.spy_ready_points[0]
        current_spy_close, current_spy_average = self.spy_ready_points[1]

        spy_crossed_above = (
            previous_spy_close <= previous_spy_average
            and current_spy_close > current_spy_average
        )
        spy_crossed_below = (
            previous_spy_close >= previous_spy_average
            and current_spy_close < current_spy_average
        )

        spy_sold = False
        aapl_sold = False

        spy_quantity = self.Portfolio[self.spy].Quantity
        if (
            spy_quantity > 0
            and not self._has_open_orders(self.spy)
            and spy_crossed_below
        ):
            self.MarketOrder(
                self.spy, -spy_quantity, False, "Strategy A: liquidate lot"
            )
            spy_sold = True

        aapl_quantity = self.Portfolio[self.aapl].Quantity
        if (
            aapl_quantity > 0
            and not self._has_open_orders(self.aapl)
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(
                self.aapl, -aapl_quantity, False, "Strategy B: liquidate lot"
            )
            aapl_sold = True

        if (
            not spy_sold
            and self.Portfolio[self.spy].Quantity == 0
            and not self._has_open_orders(self.spy)
            and spy_crossed_above
        ):
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.MarketOrder(
                    self.spy, quantity, False, "Strategy A: invest 40%"
                )

        if (
            not aapl_sold
            and self.Portfolio[self.aapl].Quantity == 0
            and not self._has_open_orders(self.aapl)
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            close = Decimal(str(aapl_bar.Close))
            quantity = int(
                (Decimal("20000") / close).to_integral_value(
                    rounding=ROUND_FLOOR
                )
            )
            if quantity > 0:
                self.MarketOrder(
                    self.aapl, quantity, False, "Strategy B: buy $20,000"
                )

    def _get_real_bar(self, data, symbol):
        if not data.Bars.ContainsKey(symbol):
            return None

        bar = data.Bars[symbol]
        if bar is None or bar.IsFillForward:
            return None

        return bar

    def _has_open_orders(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

