from AlgorithmImports import *
from collections import deque
import math


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.subscribed_symbols = list(self.symbols.values())

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.spy_cross_above = False
        self.spy_cross_below = False
        self.spy_cross_ready = False
        self.spy_last_end_time = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_current_close = None
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )
        self.aapl_last_end_time = None

        self.last_evaluation_time = None

        # One prior fully formed SMA value is required to detect a cross.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for symbol in self.subscribed_symbols:
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if bar is not None:
                    bars[symbol] = bar

        # Market-state quantities continue updating even when another
        # subscribed ticker has no bar.
        if self.spy in bars:
            self.UpdateSpyState(bars[self.spy])

        if self.aapl in bars:
            self.UpdateAaplState(bars[self.aapl])

        if self.IsWarmingUp:
            return

        # A missing bar for any subscribed ticker skips every rule.
        if len(bars) != len(self.subscribed_symbols):
            return

        evaluation_time = bars[self.spy].EndTime
        if self.last_evaluation_time == evaluation_time:
            return
        self.last_evaluation_time = evaluation_time

        if not self.spy_cross_ready or not self.aapl_rsi.IsReady:
            return

        spy_quantity = self.Portfolio[self.spy].Quantity
        aapl_quantity = self.Portfolio[self.aapl].Quantity

        # Evaluate all sells before any buys.
        if (
            spy_quantity > 0
            and not self.HasOpenOrders(self.spy)
            and self.spy_cross_below
        ):
            self.MarketOrder(
                self.spy,
                -spy_quantity,
                tag="Strategy A: SPY crossed below 100-day SMA"
            )

        if (
            aapl_quantity > 0
            and not self.HasOpenOrders(self.aapl)
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self.MarketOrder(
                self.aapl,
                -aapl_quantity,
                tag="Strategy B: AAPL RSI above 60"
            )

        # Strategy A buy.
        if (
            spy_quantity == 0
            and not self.HasOpenOrders(self.spy)
            and self.spy_cross_above
        ):
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A: SPY crossed above 100-day SMA"
                )

        # Strategy B buy.
        if (
            aapl_quantity == 0
            and not self.HasOpenOrders(self.aapl)
            and self.aapl_red_streak >= 3
        ):
            available_cash = float(self.Portfolio.Cash)
            if available_cash >= 20_000.0:
                quantity = int(
                    math.floor(20_000.0 / self.aapl_current_close)
                )
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B: AAPL red for at least 3 days"
                    )

    def UpdateSpyState(self, bar: TradeBar):
        if self.spy_last_end_time == bar.EndTime:
            return
        self.spy_last_end_time = bar.EndTime

        close = float(bar.Close)
        self.spy_closes.append(close)

        self.spy_cross_above = False
        self.spy_cross_below = False
        self.spy_cross_ready = False

        if len(self.spy_closes) == 100:
            current_sma = sum(self.spy_closes) / 100.0

            if (
                self.spy_previous_close is not None
                and self.spy_previous_sma is not None
            ):
                self.spy_cross_ready = True
                self.spy_cross_above = (
                    self.spy_previous_close <= self.spy_previous_sma
                    and close > current_sma
                )
                self.spy_cross_below = (
                    self.spy_previous_close >= self.spy_previous_sma
                    and close < current_sma
                )

            self.spy_previous_sma = current_sma

        self.spy_previous_close = close

    def UpdateAaplState(self, bar: TradeBar):
        if self.aapl_last_end_time == bar.EndTime:
            return
        self.aapl_last_end_time = bar.EndTime

        close = float(bar.Close)
        self.aapl_current_close = close

        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_previous_close = close
        self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def HasOpenOrders(self, symbol: Symbol) -> bool:
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

